import{_ as r,c as e,a as m,o as t}from"./app-C8nc19Re.js";const n={};function k(s,a){return t(),e("div",null,a[0]||(a[0]=[m('<h2 id="介绍" tabindex="-1"><a class="header-anchor" href="#介绍"><span>介绍</span></a></h2><p>后台页面支持可视化的操作，包括 <mark>表单</mark>、<mark>表格</mark>、<mark>图表</mark> 等，通过拖拽组件的方式快速生成页面，无需编写代码。右下角的按钮可以切换关闭开发模式，关闭后即可以预览线上效果。 右下角菜单中包含了菜单，模型，配置的管理页面，可以方便地管理后台页面。</p><h2 id="模型" tabindex="-1"><a class="header-anchor" href="#模型"><span>模型</span></a></h2><div class="hint-container info"><p class="hint-container-title">模型即是数据结构，用于描述数据及其关系。模型是数据表结构的抽象，通过定义模型，可以方便地操作数据库中的数据。</p></div><p>开发一个功能的第一步一般是创建一张数据表，定义好表结构后，再创建模型，控制器，视图文件。</p><p>这里我们也是先创建一个模型，在模型中配置数据表字段，再进行一些其它配置后，保存之后自动会创建好数据表，控制器，模型文件。</p><p>创建好的控制器，模型文件都包含了自定义代码块区域，修改编辑模型时不会覆盖自定义代码块区域中的内容。</p><p>修改模型时如果勾选了生成表选项后，在 <mark>dev_sqllog</mark> 表中会记录下当前模型的 sql 语句，方便查看修改记录，更新到线上时只要复制sql语句就可以对表进行更新。</p><h2 id="菜单" tabindex="-1"><a class="header-anchor" href="#菜单"><span>菜单</span></a></h2><p>菜单分为 <mark>列表</mark> <mark>表单</mark> <mark>面板</mark> 3个主要分类。<mark>列表</mark> 又分为 <mark>列表</mark> <mark>树形列表</mark> <mark>卡片列表</mark> 3个类型。</p><p>菜单可以现在创建好的模型，如果是列表类型系统会默认创建一个resource包含增删改查的路由，其它类型会创建单独的路由，所以创建的菜单即是后台权限控制，可以控制用户访问权限。</p><p>菜单页面可以进行 <mark>可视化</mark> 管理操作，包括拖拽排序,更换组件类型，编辑当前项的属性等</p><p>因为可视化的操作所以后台的页面都是动态生成的，是没有文件的，相当于前端页面无代码 <mark>所有页面都是可视化操作后生成json配置后显示出来的</mark> 的状态，但是如果你想要自定义页面，那么可以启动 <mark>deadmindev</mark> 的项目，自行创建自定义页面，配置页面路由信息等。相关技术栈 <mark>React</mark> <mark>Antdesign</mark> <mark>Npm</mark>等。</p><p>鉴于系统包含丰富的组件，及 <mark>自定义组件</mark> ，一般后台系统的页面都是可以轻松实现的。</p><h2 id="配置" tabindex="-1"><a class="header-anchor" href="#配置"><span>配置</span></a></h2><p>配置包含了 <mark>系统名称</mark> <mark>logo</mark> <mark>底部版权</mark> <mark>水印设置</mark> <mark>登录页面设置</mark> <mark>地图配置</mark> <mark>主题配置</mark> <mark>websocket配置</mark> <mark>自定义iconfont</mark> <mark>上传配置</mark> 等功能</p><h2 id="更新至线上" tabindex="-1"><a class="header-anchor" href="#更新至线上"><span>更新至线上</span></a></h2><p>线上环境一般是不开启开发模式的，开发菜单路径和线下是一样的。在开发环境下编辑模型会重新生成一遍控制器和模型文件，更新的话使用git提交即可，更新菜单的话需要在开发菜单页面或者当前菜单页面导出菜单数据，会导出一个后缀是.sql的文件，然后在线上环境的开发菜单管理页面中导入该文件即可。</p>',18)]))}const p=r(n,[["render",k]]),o=JSON.parse('{"path":"/guide/intro/","title":"操作说明","lang":"zh-CN","frontmatter":{"title":"操作说明","createTime":"2025/04/17 13:50:26","permalink":"/guide/intro/"},"readingTime":{"minutes":2.82,"words":846},"git":{"updatedTime":1746846312000,"contributors":[{"name":"echoyl","username":"echoyl","email":"inandan@126.com","commits":1,"avatar":"https://avatars.githubusercontent.com/echoyl?v=4","url":"https://github.com/echoyl"}]},"filePathRelative":"notes/guide/quick-start/intro.md","headers":[]}');export{p as comp,o as data};
